def bell_number(n):
    if n == 1:
        return 1
    B = [0]*(n+1)
    B[1] = 1
    for i in range(2, n+1):
        B[i] = sum(comb(i-1,j) * B[j] for j in range(i))
    return B[n]

def comb(n, k):
    if k > n-k: k = n-k
    result = 1
    for i in range(k): result = result * (n - i) / (i + 1)
    return result

